import {chromium} from '@playwright/test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {KEY,scenarioState} from '../src/model.js';
import {freezeReport} from '../src/alignment-model.js';
import {planningReportBody} from '../src/continuity-model.js';
const base='http://127.0.0.1:5184',dir='检查记录/报告简历重设计_20261021';
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});
const p=await browser.newPage({viewport:{width:1440,height:1000}}),results=[],errors=[];p.setDefaultTimeout(7000);p.on('pageerror',e=>errors.push(e.message));
async function load(route,s='PT05',width=1440,lang='zh'){await p.setViewportSize({width,height:width<720?844:1000});await p.goto(base);await p.evaluate(({s,k,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true,active:null,seen:[]}));},{s:typeof s==='string'?scenarioState(s):s,k:KEY,lang});await p.goto(base+route);await p.locator('.output-workspace').waitFor();await p.emulateMedia({reducedMotion:'reduce'});await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});const toast=p.locator('.toast.show button');if(await toast.count())await toast.click();}
const state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function shot(name,selector){await p.locator(selector).evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/'+name+'-视口.png'});const v=p.viewportSize(),box=await p.locator(selector).boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+650)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await p.locator(selector).screenshot({path:dir+'/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,800));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('报告首要呈现阶段判断、真实材料与下一步，私人复盘正文不泄露',async()=>{const s=scenarioState('PT05');s.reviews=[{id:'private',result:'PRIVATE_RESULT',reason:'PRIVATE_REASON',next:'PRIVATE_NEXT'}];await load('/reports',s);assert.equal(await p.locator('.output-report-nav button').count(),4);assert.equal(await p.locator('.archive-edition-cover').count(),0);assert.equal(await p.locator('.output-report-takeaways section').count(),2);assert.doesNotMatch(await p.locator('.output-report-desk').innerText(),/PRIVATE_/);await shot('1440-报告摘要','.output-report-desk');await p.getByRole('button',{name:'选择与依据',exact:false}).click();assert.equal(await p.locator('.output-evidence-list article').count(),2);await p.getByRole('button',{name:'完整报告',exact:false}).click();assert.equal(await p.locator('.report-topic-panel').count(),11);assert.doesNotMatch(await p.locator('.output-report-desk').innerText(),/PRIVATE_/);await p.getByRole('button',{name:'阶段摘要',exact:false}).click();});
await check('选择记录可编辑、取消与保存，既有快照保持冻结',async()=>{const s=scenarioState('PT05');s.decision.reason='OLD_REASON';const r=freezeReport(s,'保存的合成报告',planningReportBody(s));s.reports=[r];await load('/reports',s);await p.getByRole('button',{name:'编辑选择与问题',exact:true}).click();await p.getByLabel('我的选择理由',{exact:true}).fill('NEW_REASON');await p.getByRole('button',{name:'取消编辑',exact:true}).click();assert.equal((await state()).decision.reason,'OLD_REASON');await p.getByRole('button',{name:'编辑选择与问题',exact:true}).click();await p.getByLabel('我的选择理由',{exact:true}).fill('NEW_REASON');await p.getByLabel('我的阶段判断',{exact:true}).fill('先验证数据质量任务');await p.getByRole('button',{name:'保存选择记录',exact:true}).click();assert.equal((await state()).decision.reason,'NEW_REASON');assert.equal((await state()).reports[0].body,r.body);await p.getByRole('link',{name:'打开报告 →',exact:true}).click();assert.match(await p.locator('.output-snapshot-summary').innerText(),/OLD_REASON/);assert.doesNotMatch(await p.locator('.output-snapshot-summary').innerText(),/NEW_REASON/);await shot('1440-保存报告','.output-workspace');});
await check('报告创建、编辑另存与片段导出仍可完成；撤回后不显示缓存',async()=>{await load('/reports');await p.getByRole('button',{name:'创建报告 · 先检查缺项',exact:true}).click();const dialog=p.locator('dialog[open]');await dialog.locator('.alignment-dialog>label.check input').check();await dialog.getByRole('button',{name:'冻结输入并建立模拟草稿',exact:true}).click();await p.waitForURL(u=>u.pathname.startsWith('/reports/'));const before=(await state()).reports.length;await p.getByRole('button',{name:'编辑报告正文',exact:true}).click();await p.getByLabel('章节正文 / 人工编辑草稿（自动保留）').fill((await p.getByLabel('章节正文 / 人工编辑草稿（自动保留）').inputValue())+'\n人工补充：这是本人确认的新增想法');await p.getByRole('button',{name:'人工编辑另存新版本',exact:true}).click();assert.equal((await state()).reports.length,before+1);await p.getByRole('button',{name:'选择片段导出',exact:true}).click();const [download]=await Promise.all([p.waitForEvent('download'),dialog.getByRole('button',{name:'导出选中片段 TXT（本地示例）',exact:true}).click()]);assert.match(download.suggestedFilename(),/\.txt$/);assert.match(await fs.readFile(await download.path(),'utf-8'),/本人确认的新增想法/);await dialog.getByRole('button',{name:'关闭面板',exact:true}).click();const s=await state(),r=s.reports.at(-1);s.claims[0].status='已撤回';await load('/reports/'+r.id,s);assert.equal(await p.locator('.output-snapshot-summary').count(),0);assert.equal(await p.getByRole('button',{name:'编辑报告正文',exact:true}).isDisabled(),true);assert.doesNotMatch(await p.locator('.report-paper').innerText(),/这是本人确认的新增想法/);});
await check('简历默认可编辑目标与材料，成稿同步排序与选用，原事实不改写',async()=>{const s=scenarioState('PT05');s.resumeTarget='job-a';await load('/reports?tab=岗位简历',s);assert.equal(await p.locator('.output-resume-steps button').count(),3);assert.equal(await p.getByLabel('目标岗位',{exact:true}).isVisible(),true);await p.getByLabel('姓名（示例用途，不参与分析）').fill('合成测试用户');assert.match(await p.locator('.output-resume-paper>header').innerText(),/合成测试用户/);const claims=(await state()).claims;await p.getByRole('button',{name:'上移经历：SQL 报告（合成示例）',exact:true}).click();assert.match(await p.locator('.output-resume-experience').first().innerText(),/SQL 报告/);await p.locator('.resume-configuration input[name=claims]').first().uncheck();assert.equal(await p.locator('.output-resume-experience').count(),1);assert.deepEqual((await state()).claims,claims);await p.locator('.resume-configuration input[name=claims]').first().check();await shot('1440-简历编辑','.output-resume');});
await check('岗位表达在编辑区逐条选事实、改写并确认，保存与输出沿用同一草稿',async()=>{await p.getByRole('button',{name:'岗位表达',exact:true}).click();const row=p.locator('.output-tailoring .jd-tailor .record').first();await row.locator('input[type=checkbox]').first().check();await row.getByRole('button',{name:'生成此项模拟措辞',exact:true}).click();await row.getByLabel('要求1的表达',{exact:true}).fill('本人整理了问题清单，并保留输入与结果限制。');await row.getByRole('checkbox',{name:'确认这段表达不超出所选事实',exact:true}).check();assert.match(await p.locator('.output-confirmed-wording').innerText(),/本人整理了问题清单/);await shot('1440-岗位表达','.output-resume');await p.getByRole('button',{name:'保存前检查',exact:true}).click();assert.equal(await p.locator('.output-resume-check li').count(),5);await p.locator('.output-resume-toolbar').getByRole('button',{name:'核对原文与措辞差异',exact:true}).click();const dialog=p.locator('dialog[open]');await dialog.getByRole('button',{name:'本人确认并保存简历版本',exact:true}).click();assert.equal((await state()).resumes.length,1);assert.match((await state()).resumes[0].tailoring.rows[0].wording,/问题清单/);await p.locator('.resume-history').getByRole('button',{name:'查看 / 打印为 PDF（模拟输出）',exact:true}).click();assert.match(await p.locator('#printable').innerText(),/问题清单/);await dialog.getByRole('button',{name:'关闭面板',exact:true}).click();await p.locator('.resume-citation').first().click();assert.equal(await p.getByRole('region',{name:'简历依据批注',exact:true}).isVisible(),true);await p.getByRole('button',{name:'返回内容编辑',exact:true}).click();await p.getByLabel('目标岗位',{exact:true}).selectOption('job-b');assert.equal(Object.keys((await state()).resumeStudioDraft.tailoring).length,0);assert.equal((await state()).resumes[0].target,'job-a');});
await check('空态、手机长文与英文检查不溢出，最后动作高于底栏',async()=>{for(const [name,route,s,lang]of [['390-报告空态','/reports',scenarioState('PT01'),'zh'],['390-报告摘要','/reports',scenarioState('PT05'),'zh'],['390-简历空态','/reports?tab=岗位简历',scenarioState('PT01'),'zh'],['390-简历编辑','/reports?tab=岗位简历',scenarioState('PT05'),'zh'],['390-报告英文','/reports',scenarioState('PT01'),'en'],['390-简历英文','/reports?tab=岗位简历',scenarioState('PT01'),'en']]){if(name==='390-简历编辑')s.claims[0].title='合成长标题用于测试换行'.repeat(12);await load(route,s,390,lang);const selector=route.includes('tab')?'.output-resume':'.output-report-desk';assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await p.locator(selector).evaluate(e=>e.scrollWidth>e.clientWidth),false);if(lang==='en'){const chinese=(await p.locator(selector).innerText()).match(/[\u4e00-\u9fff]+/g);assert.equal(chinese,null,JSON.stringify(chinese));}await shot(name,selector);const last=p.locator(selector).locator('a').last();await last.scrollIntoViewIfNeeded();const a=await last.boundingBox(),flow=await p.locator('.flow-progress').boundingBox();assert.ok(a.y+a.height<flow.y+1);await p.screenshot({path:dir+'/'+name+'-底部.png'});}});
await check('独立复核修正：手机长内容可往返成稿并恢复焦点，主操作14px与44px',async()=>{for(const width of [1440,390]){const s=scenarioState('PT05');s.claims[0].title='长标题合成经历用于往返测试'.repeat(12);s.resumeTarget='job-a';await load('/reports?tab=岗位简历',s,width);for(const selector of ['.output-resume-actions>.primary','.resume-configuration form>.primary']){const size=await p.locator(selector).evaluate(e=>({font:parseFloat(getComputedStyle(e).fontSize),height:e.getBoundingClientRect().height}));assert.ok(size.font>=14,JSON.stringify(size));assert.ok(size.height>=44,JSON.stringify(size));}await p.getByRole('button',{name:'查看成稿 ↓',exact:true}).click();assert.equal(await p.locator('.output-resume-paper').evaluate(e=>document.activeElement===e),true);await p.screenshot({path:dir+'/'+width+'-直接查看成稿.png'});const citation=p.locator('.resume-citation').first();await citation.click();assert.equal(await p.locator('.output-resume-source').evaluate(e=>document.activeElement===e),true);assert.equal(await p.locator('.output-resume-source dd').first().evaluate(e=>getComputedStyle(e).color),'rgb(37, 37, 37)');await shot(width+'-来源核对','.output-resume-source');await p.getByRole('button',{name:'返回成稿中的这段经历 →',exact:true}).click();assert.equal(await citation.evaluate(e=>document.activeElement===e),true);await p.screenshot({path:dir+'/'+width+'-返回成稿焦点.png'});await citation.click();await p.getByRole('button',{name:'返回内容编辑',exact:true}).click();await p.waitForFunction(()=>document.activeElement?.classList.contains('output-resume-editor'));assert.equal(await p.getByLabel('目标岗位',{exact:true}).isVisible(),true);assert.equal(await p.locator('.output-resume').evaluate(e=>e.scrollWidth>e.clientWidth),false);}});
await check('失效岗位不冒充通用简历，空材料不能绕过保存',async()=>{const s=scenarioState('PT01');s.resumeStudioDraft={target:'missing',targetSeed:'',claimIds:[],educationIds:[]};await load('/reports?tab=岗位简历',s);await p.locator('.output-resume-toolbar').getByRole('button',{name:'核对原文与措辞差异',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),0);assert.match(await p.locator('.toast').innerText(),/原岗位已不可用/);await p.getByLabel('目标岗位',{exact:true}).selectOption('');await p.locator('.output-resume-toolbar').getByRole('button',{name:'核对原文与措辞差异',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),0);assert.match(await p.locator('.toast').innerText(),/至少一项/);});
assert.equal(errors.length,0);results.push({name:'浏览器运行时错误',status:'pass',count:errors.length});
}finally{await fs.writeFile(dir+'/浏览器验收.json',JSON.stringify({results,errors},null,2));await browser.close();}
if(results.some(r=>r.status==='fail'))process.exitCode=1;
